59	        _cursorSet = world.GetEntities().With<CursorInputComponent>().AsSet();
60	        _gizmoStateSet = world.GetEntities().With<GizmoStateComponent>().AsSet();
61	        _grids = world.GetEntities().With<TileGridComponent>().With<TransformComponent>().AsSet();
62	    }
