111	        // A fast drag can jump more than one cell between frames — walk the line from the previous
112	        // cursor cell so the stroke never leaves holes (the brush paints a continuous path).
113	        if (_lastCell is { } from && (Math.Abs(from.X - x) > 1 || Math.Abs(from.Y - y) > 1))
114	        {
115	            var steps = Math.Max(Math.Abs(from.X - x), Math.Abs(from.Y - y));
116	            for (var i = 1; i < steps; i++)
117	            {
118	                var ix = from.X + (int)Math.Round((x - from.X) * (i / (float)steps));
119	                var iy = from.Y + (int)Math.Round((y - from.Y) * (i / (float)steps));
