128	    private void PaintCell(Entity grid, TileGridComponent data, int x, int y, byte value)
129	    {
130	        var key = TileGridComponent.Pack(x, y);
131	        if (_lastPaintedCell == key) return; // still in the same cell
132	        _lastPaintedCell = key;
133	
134	        var before = data.Cells.TryGetValue(key, out var current) ? current : (byte)0;
135	        if (before == value) return; // already that value — nothing to record
136	
137	        _history.Push(new TileGridPaintCommand(grid, key, before, value));
138	    }
