2	using DefaultEcs;
3	using MonoDreams.Component.Level;
4	
5	namespace MonoDreams.LevelEditor.Undo;
6	
7	/// <summary>
8	/// One edit of a <see cref="TilePaintValue"/>'s VISUAL definition — its autotile rules and/or its
9	/// tileset binding (key + tile size) — as before/after snapshots keyed by the value's stable
10	/// <see cref="TilePaintValue.Id"/> (indices shift when values are added/removed; ids never do).
11	/// The Autotile Rules workspace pushes one of these per edit (a case's tile toggle, a tileset
12	/// pick), so rules editing is LIVE — the world re-skins immediately (Apply/Revert publish
13	/// <c>NotifyChanged</c>, the bake's trigger) — and every step undoes through the ONE shared history
14	/// like any other scene edit. No Save/Cancel layer: the history IS the safety net.
15	/// </summary>
16	public sealed class PaintValueEditCommand : IEditorCommand
17	{
18	    private readonly Entity _grid;
19	    private readonly byte _valueId;
20	    private readonly string? _rulesBefore, _rulesAfter;
21	    private readonly string? _tilesetBefore, _tilesetAfter;
22	    private readonly int _tileSizeBefore, _tileSizeAfter;
23	
24	    private PaintValueEditCommand(Entity grid, byte valueId,
25	        string? rulesBefore, string? rulesAfter,
26	        string? tilesetBefore, string? tilesetAfter,
27	        int tileSizeBefore, int tileSizeAfter)
28	    {
29	        _grid = grid;
30	        _valueId = valueId;
31	        _rulesBefore = rulesBefore;
32	        _rulesAfter = rulesAfter;
33	        _tilesetBefore = tilesetBefore;
34	        _tilesetAfter = tilesetAfter;
35	        _tileSizeBefore = tileSizeBefore;
36	        _tileSizeAfter = tileSizeAfter;
37	    }
38	
39	    /// <summary>An autotile-rules edit (tileset unchanged).</summary>
40	    public static PaintValueEditCommand Rules(Entity grid, TilePaintValue value, string? newRules) =>
41	        new(grid, value.Id, value.AutotileRules, newRules,
42	            value.TilesetKey, value.TilesetKey, value.TileSize, value.TileSize);
43	
44	    /// <summary>A tileset re-bind (rules unchanged — the mapping usually still applies; masks are
45	    /// sheet-agnostic and cell indices are the designer's to fix up next).</summary>
46	    public static PaintValueEditCommand Tileset(Entity grid, TilePaintValue value, string? newKey, int newTileSize) =>
47	        new(grid, value.Id, value.AutotileRules, value.AutotileRules,
48	            value.TilesetKey, newKey, value.TileSize, newTileSize);
49	
50	    public void Apply(World world) => Write(_rulesAfter, _tilesetAfter, _tileSizeAfter);
51	
52	    public void Revert(World world) => Write(_rulesBefore, _tilesetBefore, _tileSizeBefore);
53	
