307	+            Notifications.Notify("No asset catalog on this screen", EditorNotifySeverity.Warning);
308	+            return;
309	+        }
310	+
311	+        // Distinct sheets: sliced entries collapse to their sheet file (slice size = tile size);
312	+        // whole-PNG static entries offer themselves at the 32px default. Sequences are animations,
313	+        // not tilesets — skipped.
314	+        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
315	+        var items = new List<EditorMenuItem>();
316	+        foreach (var entry in _assetCatalog.Entries)
317	+        {
318	+            if (entry.IsSequence) continue;
319	+            var isSlice = entry.Region is { } region && region.Width > 0;
320	+            var tileSize = entry.Region is { } r ? Math.Max(1, Math.Min(r.Width, r.Height)) : 32;
321	+            if (!seen.Add(entry.RelativePath)) continue;
322	+            var stem = Path.GetFileNameWithoutExtension(entry.RelativePath);
323	+            items.Add(new EditorMenuItem
324	+            {
325	+                Kind = EditorMenuItemKind.Action,
326	+                Label = isSlice ? $"{stem}  ({tileSize}px grid)" : stem,
327	+                Path = RulesTilesetPath + tileSize.ToString(CultureInfo.InvariantCulture) + "|"
328	+                       + FileAssetKey.Compose(entry.RelativePath, null),
329	+            });
