1	#nullable enable
2	using System;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using MonoDreams.Component;
7	using MonoDreams.Component.Cursor;
8	using MonoDreams.Component.Level;
9	using MonoDreams.LevelEditor.Component;
10	using MonoDreams.LevelEditor.UI;
11	using MonoDreams.LevelEditor.Undo;
12	using MonoDreams.State;
13	
14	namespace MonoDreams.LevelEditor.System;
15	
16	/// <summary>
17	/// The tile-grid paint brush (the <see cref="EditorToolMode.GroundPaint"/> owner): while the
18	/// palette's Paint tab has a <c>TilePaintValue</c> armed (<see cref="GizmoStateComponent.PaintValue"/>;
19	/// 0 = eraser), holding the left button paints the cell under the cursor — a drag paints every cell
20	/// crossed, each edit one <see cref="TileGridPaintCommand"/> pushed into a coalescing history
21	/// transaction, so the whole stroke is ONE undo step (the gizmo-drag pattern). Every applied edit
22	/// publishes <c>NotifyChanged</c>; the bake system re-derives tiles + colliders after its quiet
23	/// window, while the paint-view overlay shows the logical cells live.
24	///
25	/// <para><b>The grid the brush targets.</b> The brush paints into the ACTIVE Paint layer's
26	/// <see cref="TileGridComponent"/> (a Paint layer IS its grid — the layers model), so arming is
27	/// layer-driven and the target is never ambiguous. A single-grid LEGACY scene (a bare grid entity
28	/// predating the layers model) is upgraded into a real Paint layer on the first paint and activated,
29	/// so old scenes join the model without a migration. With no Paint layer the brush refuses loud
30	/// (pointing at the Entities panel's "New Indexed Layer"), a LOCKED layer refuses loud (the Aseprite
31	/// rule the palette's placement follows), and painting inside a prefab context refuses loud too (a
32	/// prefab is a class; the scene's terrain grid is scene content).</para>
33	/// </summary>
34	public sealed class TileGridPaintSystem : ISystem<GameState>
35	{
36	    private readonly World _world;
37	    private readonly EditorHistory _history;
38	    private readonly EditorShellStateComponent? _shellState;
39	    private readonly Action<string>? _notifyWarning;
40	    private readonly EntitySet _cursorSet;
41	    private readonly EntitySet _gizmoStateSet;
42	    private readonly EntitySet _grids;
43	
44	    private bool _stroking;
45	    private bool _refusalLogged; // one log line per stroke — a held drag must not spam the log
46	    private long? _lastPaintedCell;
47	    private (int X, int Y)? _lastCell; // the previous frame's cursor cell — fast drags interpolate
48	
49	    public bool IsEnabled { get; set; } = true;
50	
51	    public TileGridPaintSystem(World world, EditorHistory history,
52	        EditorShellStateComponent? shellState = null,
53	        Action<string>? notifyWarning = null)
54	    {
55	        _world = world ?? throw new ArgumentNullException(nameof(world));
56	        _history = history ?? throw new ArgumentNullException(nameof(history));
57	        _shellState = shellState;
58	        _notifyWarning = notifyWarning;
59	        _cursorSet = world.GetEntities().With<CursorInputComponent>().AsSet();
60	        _gizmoStateSet = world.GetEntities().With<GizmoStateComponent>().AsSet();
61	        _grids = world.GetEntities().With<TileGridComponent>().With<TransformComponent>().AsSet();
62	    }
63	
64	    public void Update(GameState state)
65	    {
66	        if (!IsEnabled) return;
67	        if (state.RunMode != RunMode.Edit)
68	        {
69	            EndStroke();
70	            return;
71	        }
72	
73	        var gizmo = ReadGizmoState();
74	        if (gizmo.Mode != EditorToolMode.GroundPaint)
75	        {
76	            EndStroke();
77	            return;
78	        }
79	
80	        foreach (var cursor in _cursorSet.GetEntities())
81	        {
82	            ref readonly var input = ref cursor.Get<CursorInputComponent>();
83	
84	            if (input.LeftButtonPressed && !input.OutsideViewport)
85	            {
86	                _history.BeginTransaction();
87	                _stroking = true;
88	                _refusalLogged = false;
89	                _lastPaintedCell = null;
90	                _lastCell = null;
91	            }
92	
93	            if (_stroking && input.LeftButton && !input.OutsideViewport)
94	                PaintAt(input.WorldPosition, gizmo.PaintValue);
95	
96	            if (_stroking && (input.LeftButtonReleased || !input.LeftButton))
97	                EndStroke();
98	
99	            return; // single cursor
100	        }
101	    }
102	
103	    private void PaintAt(Vector2 worldPosition, byte value)
104	    {
105	        var grid = FindOrCreateGrid(value);
106	        if (grid == null) return;
107	
108	        var data = grid.Value.Get<TileGridComponent>();
109	        var anchor = grid.Value.Get<TransformComponent>().WorldPosition;
110	        var (x, y) = data.CellAt(worldPosition, anchor);
111	
112	        // A fast drag can jump more than one cell between frames — walk the line from the previous
113	        // cursor cell so the stroke never leaves holes (the brush paints a continuous path).
114	        if (_lastCell is { } from && (Math.Abs(from.X - x) > 1 || Math.Abs(from.Y - y) > 1))
115	        {
116	            var steps = Math.Max(Math.Abs(from.X - x), Math.Abs(from.Y - y));
117	            for (var i = 1; i < steps; i++)
118	            {
119	                var ix = from.X + (int)Math.Round((x - from.X) * (i / (float)steps));
120	                var iy = from.Y + (int)Math.Round((y - from.Y) * (i / (float)steps));
121	                PaintCell(grid.Value, data, ix, iy, value);
122	            }
123	        }
124	        _lastCell = (x, y);
125	
126	        PaintCell(grid.Value, data, x, y, value);
127	    }
128	
129	    private void PaintCell(Entity grid, TileGridComponent data, int x, int y, byte value)
130	    {
131	        var key = TileGridComponent.Pack(x, y);
132	        if (_lastPaintedCell == key) return; // still in the same cell
133	        _lastPaintedCell = key;
134	
135	        var before = data.Cells.TryGetValue(key, out var current) ? current : (byte)0;
136	        if (before == value) return; // already that value — nothing to record
137	
138	        _history.Push(new TileGridPaintCommand(grid, key, before, value));
139	    }
140	
141	    /// <summary>The grid the brush paints into — the ACTIVE layer's <see cref="TileGridComponent"/>
142	    /// (layers wave: a Paint layer IS its grid). Loud null when the active layer is not a Paint
143	    /// layer (arming is layer-driven, so this is a self-heal path, not the normal flow) or when the
144	    /// target layer is LOCKED (the placement rule: a locked layer refuses the edit, loud).</summary>
145	    private Entity? FindOrCreateGrid(byte value)
146	    {
147	        if (PrefabContextRoot.ResolveIfPrefab(_world, _shellState).IsAlive)
148	        {
149	            _notifyWarning?.Invoke("Painting is scene-only - a prefab has no terrain grid");
150	            return null;
151	        }
152	
153	        var active = _shellState?.ActiveLayer ?? default;
154	        if (active.IsAlive && active.Has<TileGridComponent>())
155	            return RefuseIfLocked(active);
156	
157	        // Fallback: exactly one paint grid in the scene — paint into it (and activate it). A
158	        // LEGACY grid entity (pre-layers "PaintGrid") is upgraded into a real Paint layer here,
159	        // so old scenes join the layers model the first time they are painted.
160	        Entity only = default;
161	        var count = 0;
162	        foreach (var grid in _grids.GetEntities()) { only = grid; count++; }
163	        if (count == 1)
164	        {
165	            if (RefuseIfLocked(only) == null) return null;
166	            if (!only.Has<SceneLayerComponent>())
167	            {
168	                only.Set(new SceneLayerComponent { Order = 0 });
169	                Logger.Info("[level-editor] Upgraded the legacy paint grid into a Paint layer.");
170	            }
171	            if (_shellState != null) _shellState.ActiveLayer = only;
172	            return only;
173	        }
174	
175	        _notifyWarning?.Invoke("Select a Paint layer to paint into (Entities panel - New Indexed Layer)");
176	        return null;
177	    }
178	
179	    /// <summary>Passes <paramref name="layer"/> through, or refuses it LOUD (null) when it carries a
180	    /// locked <c>SceneLayerComponent</c> — the same Aseprite rule the palette's placement follows
181	    /// (a locked layer is not an edit target, and a silent no-op would read as a broken brush).</summary>
182	    private Entity? RefuseIfLocked(Entity layer)
183	    {
184	        if (!layer.Has<SceneLayerComponent>() || !layer.Get<SceneLayerComponent>().Locked) return layer;
185	        var name = MonoDreams.System.Level.SceneLayerSystem.LayerName(layer);
186	        _notifyWarning?.Invoke($"Layer '{name}' is locked - unlock it to paint");
187	        if (!_refusalLogged)
188	        {
189	            _refusalLogged = true;
190	            Logger.Warning($"[level-editor] Paint refused: the layer '{name}' is LOCKED.");
191	        }
192	        return null;
193	    }
194	
195	    private void EndStroke()
196	    {
197	        if (!_stroking) return;
198	        _stroking = false;
199	        _lastPaintedCell = null;
200	        _lastCell = null;
201	        if (_history.InTransaction) _history.CommitTransaction();
202	    }
203	
204	    private GizmoStateComponent ReadGizmoState()
205	    {
206	        foreach (var e in _gizmoStateSet.GetEntities())
207	            return e.Get<GizmoStateComponent>();
208	        return GizmoStateComponent.Default;
209	    }
210	
211	    public void Dispose()
212	    {
213	        EndStroke();
214	        _cursorSet.Dispose();
215	        _gizmoStateSet.Dispose();
216	        _grids.Dispose();
217	    }
218	}
